serverAction.entrada:
```typescript interface CreateTenantInput { // Step 1 name: string category: string cnpj?: string phone: string email: string description?: string
// Step 2 subdomain: string cep: string street: string number: string complement?: string neighborhood: string city: string state: string deliveryRadius: number
// Step 3 logoFile?: File coverFile?: File primaryColor: string } ```

serverAction.processamento:
```typescript
// 1. Upload de imagens
const logoUrl = logoFile 
  ? await uploadToStorage(logoFile, `${subdomain}/logo`)
  : null
const coverUrl = coverFile
  ? await uploadToStorage(coverFile, `${subdomain}/cover`)
  : null

// 2. Criar restaurante
const restaurant = await prisma.restaurant.create({
  data: {
    name,
    slug: generateSlug(name),
    subdomain,
    cnpj,
    category,
    phone,
    email,
    description,
    logo: logoUrl,
    cover_image: coverUrl,
    user_id: user.id,
    street,
    number,
    complement,
    neighborhood,
    city,
    state,
    zip_code: cep,
    delivery_radius: deliveryRadius,
    status: 'CLOSED',
    is_active: true,
    theme: {
      primaryColor,
      secondaryColor: '#1A1A1A',
      fontHeading: 'Inter',
      fontBody: 'Inter',
      borderRadius: '12px',
    },
  }
})

// 3. Atualizar role do usuário
await prisma.profile.update({
  where: { id: user.id },
  data: { role: 'GERENCIADOR' }
})

// 4. Criar categorias padrão
const defaultCategories = ['Lanches', 'Bebidas', 'Sobremesas']
for (const name of defaultCategories) {
  await prisma.category.create({
    data: {
      restaurant_id: restaurant.id,
      name,
      sort_order: defaultCategories.indexOf(name),
    }
  })
}

// 5. Setar cookie do restaurante
cookies().set('restaurantId', restaurant.id)

return { success: true, data: { id: restaurant.id, subdomain } }
```
